(function(root){
'use strict';
const S=root.GameSymbols,R=root.WCARecords,M=root.MiddleClass,esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const classes={Working:'労働者階級',Middle:'中産階級',Capitalist:'資本家階級',State:'国家'},resources={Food:'食料',Luxury:'ぜいたく品',Health:'医療',Education:'教育',Influence:'影響力'};
const skills={Gray:'未熟練',Green:'農業',Blue:'ぜいたく品',White:'医療',Orange:'教育',Purple:'メディア'},industries={Food:'農業',Luxury:'ぜいたく品',Health:'医療',Education:'教育',Media:'メディア'},unionSkill={Food:'Green',Luxury:'Blue',Health:'White',Education:'Orange',Media:'Purple'};
function mount(s,owner,container,button,send,options={}){
 const r=s.records,defs=Object.fromEntries([...root.WCA_COMPANIES,...root.WCA_EXTRA_COMPANIES].map(d=>[d.id,d])),definition=id=>M.definition(r,id),draft=new Map(),unions=new Set(),locked=owner==='Middle'?s.middleBasicUsed:s.workingBasicUsed;
 const companies=Object.entries(r.companies).filter(([id,c])=>c.status==='built'&&c.slots.length&&(!options.companyIds||options.companyIds.includes(id))&&!(owner==='Middle'&&defs[id].class==='Working'));
 const count=()=>draft.size+unions.size;
 const remaining=(ref,except)=>{const total=ref.startsWith('u:')?Number(r.common.unemployed[owner][ref.slice(2)]||0):1;return total-[...draft].filter(([key,w])=>key!==except&&w.ref===ref).length-(owner==='Working'&&ref.startsWith('u:')?[...unions].filter(id=>unionSkill[id]===ref.slice(2)).length:0);};
 const choices=(id,index)=>{const c=r.companies[id],d=definition(id),key=id+':'+index;if(c.slots[index]?.owner!=='empty')return [];if(owner==='Middle')return M.assignmentChoices(r,id,index).filter(w=>w.ref!==`c:${id}:${index}`&&remaining(w.ref,key)>0).map(w=>({...w,count:remaining(w.ref,key)}));const required=d.workers.flatMap((w,i)=>d.class!=='Middle'||w.type!=='MiddleClass'?[i]:[]);if(required.length>3||!required.includes(index)||!required.every(i=>c.slots[i].owner==='empty')||d.class==='Middle'&&c.operating!=='yes')return [];if(options.reassignWorking)return root.PlayerCards.workerChoices(r,true).filter(w=>R.workerFits(d.workers[index],owner,w.skill,d.class)&&remaining(w.ref,key)>0&&w.companyId!==id).map(w=>({...w,count:remaining(w.ref,key)}));return Object.keys(skills).filter(skill=>R.workerFits(d.workers[index],owner,skill,d.class)&&remaining('u:'+skill,key)>0).map(skill=>({ref:'u:'+skill,skill,count:remaining('u:'+skill,key)}));};
 const plan=()=>owner==='Middle'?{action:'AW',moves:[...draft].map(([key,w])=>{const [companyId,index]=key.split(':');return {companyId,index:Number(index),worker:w.ref};})}:options.reassignWorking?{action:'AW',allocations:[...new Set([...draft.keys()].map(key=>key.split(':')[0]))].map(companyId=>({companyId,slots:[...draft].filter(([key])=>key.startsWith(companyId+':')).map(([key,w])=>({index:Number(key.split(':')[1]),worker:w.ref}))})),unions:[]}:{action:'AW',allocations:[...new Set([...draft.keys()].map(key=>key.split(':')[0]))].map(companyId=>({companyId,skills:definition(companyId).workers.flatMap((w,i)=>definition(companyId).class!=='Middle'||w.type!=='MiddleClass'?[draft.get(companyId+':'+i)?.skill]:[])})),unions:[...unions]};
 const preview=()=>{if(!count())return {error:'空き枠をタップして、配置するワーカーを選んでください。'};for(const id of new Set([...draft.keys()].map(key=>key.split(':')[0]))){const c=r.companies[id],d=definition(id),required=d.workers.map((w,i)=>i).filter(i=>d.class!=='Middle'||(owner==='Middle'?d.workers[i].type==='MiddleClass':d.workers[i].type!=='MiddleClass'));const missing=required.filter(i=>!draft.has(id+':'+i)&&(owner==='Working'||c.slots[i].owner!=='Middle'||[...draft.values()].some(w=>w.ref===`c:${id}:${i}`)));if(missing.length)return {error:`${R.companyName(d)}：あと${missing.length}人分の配置を選んでください。`};}try{const result=owner==='Middle'?M.basic(r,s.positions,plan()):options.reassignWorking?root.PlayerCards.assignWorkers(r,plan(),3,false):R.applyWorkingBasic(r,plan(),s.positions),closed=companies.filter(([id,c])=>c.operating==='yes'&&result.companies[id].operating==='no').map(([id])=>R.companyName(definition(id)));return {message:closed.length?'移動元の'+closed.join('・')+'は操業停止し、残るワーカーは失業エリアへ戻ります。':'この配置で確定できます。配置したワーカーは誓約中になります。'};}catch(e){return {error:e.message};}};
 function workerChoice(w,i,key){
  let source=`<small>${classes[owner]}・失業労働者</small>`;
  if(!w.ref.startsWith('u:')){const id=w.ref.split(':')[1],d=definition(id),c=r.companies[id],wage=r.participants[d.class]==='human'?c.wage:({A:'L3',B:'L2',C:'L1'})[s.positions[2]],amount=d.wages[wage],resource=S.icon(d.production.resource);
   source=`<small>${classes[owner]}・誓約なし</small><span class="assignment-source-company"><span class="assignment-company-heading"><span class="assignment-owner owner-${d.class.toLowerCase()}">${classes[d.class]}の企業</span><small>${industries[d.industry]||d.industry}</small></span><b>${esc(R.companyName(d))}から移動</b><small>${({yes:'操業中',no:'操業停止',unknown:'操業状態未確認'})[c.operating]}${c.machinery?' · 機械化済み':''}${c.strike?' · ストライキ中':''}</small><span class="assignment-company-info"><span>基本生産 <b>${d.production.amount} ${resource}</b></span><span>賃金 <b>${amount==null?Object.keys(d.wages).length?'未確認':'なし':wage+'（'+amount+S.icon('vardis')+'）'}</b></span></span>${d.production.employee_bonus?`<small>労働者階級の従業員参加：＋${d.production.employee_bonus} ${resource}</small>`:''}${d.production.machinery_bonus?`<small>機械化時：＋${d.production.machinery_bonus} ${resource}</small>`:''}</span>`;
  }
  return `<button type="button" data-assignment-choice="${i}" ${count()>=3&&!draft.has(key)?'disabled':''}>${R.workerIcon(owner,w.skill)}<span class="assignment-worker-description"><b>${skills[w.skill]} × ${w.count}</b>${source}</span></button>`;
 }
 function openPicker(id,index){
  if(locked||s.pendingPlayerCard||r.companies[id]?.slots[index]?.owner!=='empty')return;const key=id+':'+index,d=definition(id),req=d.workers[index],items=choices(id,index);document.getElementById('assignmentPicker')?.remove();const dialog=document.createElement('dialog');dialog.id='assignmentPicker';dialog.className='assignment-picker';dialog.setAttribute('aria-label','配置するワーカーを選択');dialog.innerHTML=`<div class="assignment-company-heading assignment-picker-destination"><span class="assignment-owner owner-${d.class.toLowerCase()}">${classes[d.class]}の企業</span><small>${industries[d.industry]||d.industry}</small></div><h2>${esc(R.companyName(d))}</h2><p>${req.type==='Unskilled'?'任意の技能':esc(skills[req.color])+'の熟練者'}を選んでください。</p>${count()>=3&&!draft.has(key)?'<p class="notice">選択上限の3人です。別の枠の選択を取り消してください。</p>':''}<div class="assignment-worker-options">${[true,false].map(unemployed=>{const choices=items.map((w,i)=>({w,i})).filter(({w})=>w.ref.startsWith('u:')===unemployed);return choices.length?`<section class="assignment-worker-group"><h3>${unemployed?'失業ワーカー':'在職ワーカー（企業から移動）'}</h3>${choices.map(({w,i})=>workerChoice(w,i,key)).join('')}</section>`:'';}).join('')||'<p>この枠に配置できるワーカーはいません。</p>'}</div>${draft.has(key)?'<button type="button" id="assignmentRemove" class="quiet">この枠の選択を取り消す</button>':''}<button type="button" id="assignmentCancel" class="quiet">戻る</button>`;
  const close=()=>{dialog.close();dialog.remove();};dialog.querySelectorAll('[data-assignment-choice]').forEach(el=>el.onclick=()=>{draft.set(key,items[Number(el.dataset.assignmentChoice)]);close();draw();});dialog.querySelector('#assignmentRemove')?.addEventListener('click',()=>{draft.delete(key);close();draw();});dialog.querySelector('#assignmentCancel').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});document.body.append(dialog);dialog.showModal();
 }
 function companyCard(id,c){
  const d=definition(id),any=c.slots.some((x,i)=>choices(id,i).length||draft.has(id+':'+i)),reason=!any?(owner==='Working'&&!c.slots.every(x=>x.owner==='empty')?'全枠が空きの企業だけ配置できます。':owner==='Middle'&&d.class!=='Middle'&&c.slots.some(x=>x.owner==='Working')?'労働者階級と混在できません。':'必要な技能のワーカーがいないか、誓約中の枠です。'):'',wage=r.participants[d.class]==='human'?c.wage:({A:'L3',B:'L2',C:'L1'})[s.positions[2]],amount=d.wages[wage],resource=S.icon(d.production.resource);
  const slots=c.slots.map((x,i)=>{const key=id+':'+i,w=draft.get(key),moved=[...draft.values()].some(y=>y.ref===`c:${id}:${i}`),req=d.workers[i],filled=['Working','Middle'].includes(x.owner)&&!moved,requirement=req.type==='Unskilled'?'任意の技能':skills[req.color],label=w?skills[w.skill]+'・'+classes[owner]:filled?skills[x.skill]+'・'+classes[x.owner]:requirement,status=w?'選択済み':moved?'移動予定':filled?x.committed?'誓約中':'誓約なし':x.owner==='unknown'?'未確認':'空き',enabled=!locked&&(w||choices(id,i).length),icon=w?R.workerIcon(owner,w.skill):x.owner==='empty'||moved?R.vacantSlot(req,d.class):filled?R.workerIcon(x.owner,x.skill):R.vacantSlot(req,d.class,'?');
   return `<button type="button" class="assignment-slot ${filled?'occupied':''} ${w?'planned':''}" data-assignment-slot="${key}" ${enabled?'':'disabled'} aria-label="${esc(R.companyName(d)+'・'+label+'・'+status)}"><span class="assignment-person">${icon}${filled&&x.committed?'<small class="summary-commit" aria-hidden="true">◆</small>':''}</span><small>${esc(label)}</small><small>${status}</small></button>`;
  }).join('');
  return `<article class="assignment-company industry-${d.industry.toLowerCase()} ${any?'':'unavailable'}" data-assignment-company="${id}"><div class="assignment-company-heading"><span class="assignment-owner owner-${d.class.toLowerCase()}">${classes[d.class]}の企業</span><small>${industries[d.industry]||d.industry}</small></div><h4>${esc(R.companyName(d))}</h4><p class="assignment-company-state">${({yes:'操業中',no:'操業停止',unknown:'操業状態未確認'})[c.operating]}${c.machinery?' · 機械化済み':''}${c.strike?' · ストライキ中':''}</p><div class="assignment-company-info"><span>基本生産 <b>${d.production.amount} ${resource}</b></span><span>賃金 <b>${amount==null?Object.keys(d.wages).length?'未確認':'なし':wage+'（'+amount+S.icon('vardis')+'）'}</b></span></div>${d.production.employee_bonus?`<p class="assignment-company-bonus">労働者階級の従業員参加：＋${d.production.employee_bonus} ${resource}</p>`:''}${d.production.machinery_bonus?`<p class="assignment-company-bonus">機械化時：＋${d.production.machinery_bonus} ${resource}</p>`:''}<div class="assignment-slots">${slots}</div>${reason?`<small class="assignment-reason">${reason}</small>`:''}</article>`;
 }
 function draw(){
  const state=preview();container.innerHTML=`<p class="assignment-guide">① 枠をタップ → ② ワーカーを選択 → ③ 配置を確定<br><small>${owner==='Middle'||options.reassignWorking?'失業者と誓約していない在職者を選べます。移動元を閉鎖する場合、誓約中のワーカーを残せません。':'失業者を選び、企業の全スロットを同時に埋めます。'}</small></p><div class="assignment-company-grid">${companies.filter(([,c])=>c.slots.some(x=>x.owner==='empty')).map(([id,c])=>companyCard(id,c)).join('')||'<p>空きスロットがある企業はありません。</p>'}</div>${owner==='Working'&&!options.companyIds?`<details class="assignment-unions"><summary>労働組合へ配置（1人・＋${S.icon('vp',2)}）</summary><div class="assignment-union-grid">${Object.entries(industries).map(([id,label])=>{const selected=unions.has(id),skill=unionSkill[id],employed=companies.reduce((n,[cid,c])=>n+(defs[cid].industry===id?c.slots.filter(x=>x.owner==='Working').length+[...draft.keys()].filter(key=>key.startsWith(cid+':')).length:0),0),enough=remaining('u:'+skill,null)>0,reason=r.personal.Working.unions[id]?'設立済み':employed<4?`同産業で働く労働者 ${employed}/4人`:!enough?'対応色の失業者がいません':count()>=3?'選択上限3人です':'';return `<button type="button" data-assignment-union="${id}" class="${selected?'planned':''}" aria-pressed="${selected}" ${locked||!selected&&reason?'disabled':''}>${R.workerIcon('Working',skill)}<span>${label}<small>${selected?'選択済み':reason||'熟練者1人を配置'}</small></span></button>`;}).join('')}</div></details>`:''}<div class="assignment-footer"><strong>選択 ${count()}／3人</strong><p role="status">${esc(state.error||state.message)}</p><div class="buttons"><button type="button" class="quiet" data-assignment-clear ${!count()||locked?'disabled':''}>選択をリセット</button></div></div>`;
  const footer=container.querySelector('.assignment-footer .buttons');if(!options.draftOnly)footer.append(button);if(options.onChange)options.onChange(state.error?null:plan(),state.error||'');button.textContent='割り当てを確定';button.disabled=!!locked||!!s.pendingPlayerCard||!!s.playerCards?.used||!!state.error;button.onclick=()=>{if(!button.disabled)send(plan());};container.querySelectorAll('[data-assignment-slot]').forEach(el=>el.onclick=()=>{const [id,index]=el.dataset.assignmentSlot.split(':');openPicker(id,Number(index));});container.querySelector('[data-assignment-clear]').onclick=()=>{draft.clear();unions.clear();draw();};container.querySelectorAll('[data-assignment-union]').forEach(el=>el.onclick=()=>{const id=el.dataset.assignmentUnion;unions.has(id)?unions.delete(id):unions.add(id);draw();});
 }
 draw();
}
root.WorkerAssignmentUi={mount};
})(globalThis);
